ALTER TABLE `task` ADD CONSTRAINT `task_ibfk_2` FOREIGN KEY (`task_id`) REFERENCES `personnel` (`personnel_id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `task` ADD CONSTRAINT `task_ibfk_3` FOREIGN KEY (`task_id`) REFERENCES `vehicle` (`vehicle_id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `task` ADD CONSTRAINT `task_ibfk_4` FOREIGN KEY (`task_id`) REFERENCES `equipment` (`equipment_id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `victim` ADD CONSTRAINT `victim_ibfk_1` FOREIGN KEY (`victim_cnic`) REFERENCES `incident` (`incident_id`) ON DELETE CASCADE ON UPDATE CASCADE;
